import React, { useEffect, useMemo, useState } from 'react';
import { Button } from '../../../components/ui/Button';
import { Modal } from '../../../components/ui/Modal';
import { Badge } from '../../../components/ui/Badge';
import {
  BookOpen, Check, ChevronRight, ClipboardList, Edit3, Plus, Search,
  ShieldCheck, Trash2, Users, X
} from 'lucide-react';

type ActiveTab = 'streams' | 'categories' | 'rules' | 'subjects';
type MarkComponent = { id: string; name: string; maxMarks: number };
type SubjectClassification = { core: boolean; language: boolean; vocational: boolean; skill: boolean; practical: boolean; coScholastic: boolean; boardExam: boolean; optional: boolean };
interface Stream { id: string; name: string; code: string; classes: string[]; active: boolean; }
interface SubjectCategory {
  id: string; name: string; code: string; description: string; displayOrder: number;
  status: 'Active' | 'Inactive'; subjectTypeName: string; classification: SubjectClassification;
  components: MarkComponent[];
}
interface SubjectGroupRule { id: string; name: string; classes: string[]; streamIds: string[]; minSubjects: number; maxSubjects: number; subjectIds: string[]; mandatorySubjectIds: string[]; active: boolean; }
interface Subject {
  id: string; code: string; name: string; categoryId: string; mediums: string[];
  description: string; classes: string[]; streamIds: string[]; passPercent: number;
  theoryMinimum: number; practicalMinimum: number; separateTheoryPass: boolean;
  separatePracticalPass: boolean; replacementEligible: boolean; bestOfEligible: boolean;
  cgpaApplicable: boolean; boardExamApplicable: boolean;
  boardExamType: 'Theory' | 'Practical' | 'Both' | 'Oral'; externalMarksEntry: boolean;
  status: 'Active' | 'Inactive';
}

const STORAGE_KEY = 'k12-stream-subject-group-master-v2';
const CLASSES = ['Nursery', 'KG', ...Array.from({ length: 12 }, (_, index) => String(index + 1))];
const MEDIUMS = ['English', 'Gujarati', 'Hindi', 'Urdu', 'Other'];
const CLASSIFICATION_LABELS: Array<[keyof SubjectClassification, string]> = [
  ['core','Core'], ['language','Language'], ['vocational','Vocational'], ['skill','Skill / Applied'],
  ['practical','Practical'], ['coScholastic','Co-scholastic'], ['boardExam','Board examination'], ['optional','Optional / Elective']
];
const emptyClassification = (): SubjectClassification => ({ core: false, language: false, vocational: false, skill: false, practical: false, coScholastic: false, boardExam: false, optional: false });
const seedStreams: Stream[] = [
  { id:'STR-SCI', name:'Science', code:'SCI', classes:['11','12'], active:true },
  { id:'STR-COM', name:'Commerce', code:'COM', classes:['11','12'], active:true },
  { id:'STR-ART', name:'Arts & Humanities', code:'ART', classes:['11','12'], active:true }
];
const seedCategories: SubjectCategory[] = [
  { id:'CAT-LANG', name:'Language', code:'LANG', description:'Language subjects and communication skills.', displayOrder:1, status:'Active', subjectTypeName:'Language', classification:{...emptyClassification(), language:true, core:true}, components:[{id:'MC-L1',name:'Written',maxMarks:80},{id:'MC-L2',name:'Internal Assessment',maxMarks:20}] },
  { id:'CAT-SCI', name:'Science', code:'SCI', description:'Science subjects with theory and practical assessment.', displayOrder:2, status:'Active', subjectTypeName:'Academic', classification:{...emptyClassification(), core:true, practical:true, boardExam:true}, components:[{id:'MC-S1',name:'Theory',maxMarks:70},{id:'MC-S2',name:'Practical',maxMarks:30}] },
  { id:'CAT-COM', name:'Commerce', code:'COM', description:'Commerce and business subjects.', displayOrder:3, status:'Active', subjectTypeName:'Academic', classification:{...emptyClassification(), core:true, boardExam:true}, components:[{id:'MC-C1',name:'Theory',maxMarks:80},{id:'MC-C2',name:'Internal Assessment',maxMarks:20}] },
  { id:'CAT-CORE', name:'Core Academic', code:'CORE', description:'Core academic subjects across applicable classes.', displayOrder:4, status:'Active', subjectTypeName:'Academic', classification:{...emptyClassification(), core:true, boardExam:true}, components:[{id:'MC-A1',name:'Written',maxMarks:100}] },
  { id:'CAT-SKILL', name:'Applied & Skill', code:'SKILL', description:'Applied, computer, and skill-based learning.', displayOrder:5, status:'Active', subjectTypeName:'Skill', classification:{...emptyClassification(), skill:true, vocational:true, practical:true}, components:[{id:'MC-K1',name:'Theory',maxMarks:60},{id:'MC-K2',name:'Practical',maxMarks:40}] }
];
const seedSubjects: Subject[] = [
  { id:'SUB-ENG',code:'ENG',name:'English',categoryId:'CAT-LANG',mediums:['English'],description:'English language and literature.',classes:['9','10','11','12'],streamIds:['STR-SCI','STR-COM','STR-ART'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:false,bestOfEligible:true,cgpaApplicable:true,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:true,status:'Active' },
  { id:'SUB-GUJ',code:'GUJ',name:'Gujarati',categoryId:'CAT-LANG',mediums:['Gujarati'],description:'Gujarati language and literature.',classes:['9','10','11','12'],streamIds:['STR-SCI','STR-COM','STR-ART'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:false,bestOfEligible:true,cgpaApplicable:true,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:false,status:'Active' },
  { id:'SUB-MAT',code:'MAT',name:'Mathematics',categoryId:'CAT-CORE',mediums:['English','Gujarati'],description:'Mathematics and problem-solving.',classes:['6','7','8','9','10','11','12'],streamIds:['STR-SCI','STR-COM'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:true,bestOfEligible:true,cgpaApplicable:true,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:true,status:'Active' },
  { id:'SUB-PHY',code:'PHY',name:'Physics',categoryId:'CAT-SCI',mediums:['English','Gujarati'],description:'Physics with theory and laboratory practicals.',classes:['11','12'],streamIds:['STR-SCI'],passPercent:33,theoryMinimum:23,practicalMinimum:10,separateTheoryPass:true,separatePracticalPass:true,replacementEligible:false,bestOfEligible:false,cgpaApplicable:false,boardExamApplicable:true,boardExamType:'Both',externalMarksEntry:true,status:'Active' },
  { id:'SUB-CHE',code:'CHE',name:'Chemistry',categoryId:'CAT-SCI',mediums:['English','Gujarati'],description:'Chemistry with theory and laboratory practicals.',classes:['11','12'],streamIds:['STR-SCI'],passPercent:33,theoryMinimum:23,practicalMinimum:10,separateTheoryPass:true,separatePracticalPass:true,replacementEligible:false,bestOfEligible:false,cgpaApplicable:false,boardExamApplicable:true,boardExamType:'Both',externalMarksEntry:true,status:'Active' },
  { id:'SUB-BIO',code:'BIO',name:'Biology',categoryId:'CAT-SCI',mediums:['English','Gujarati'],description:'Biology with laboratory practicals.',classes:['11','12'],streamIds:['STR-SCI'],passPercent:33,theoryMinimum:23,practicalMinimum:10,separateTheoryPass:true,separatePracticalPass:true,replacementEligible:false,bestOfEligible:false,cgpaApplicable:false,boardExamApplicable:true,boardExamType:'Both',externalMarksEntry:true,status:'Active' },
  { id:'SUB-ACC',code:'ACC',name:'Accountancy',categoryId:'CAT-COM',mediums:['English','Gujarati'],description:'Financial accounting and reporting.',classes:['11','12'],streamIds:['STR-COM'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:false,bestOfEligible:false,cgpaApplicable:false,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:true,status:'Active' },
  { id:'SUB-BST',code:'BST',name:'Business Studies',categoryId:'CAT-COM',mediums:['English','Gujarati'],description:'Business organisation and management.',classes:['11','12'],streamIds:['STR-COM'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:false,bestOfEligible:false,cgpaApplicable:false,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:true,status:'Active' },
  { id:'SUB-ECO',code:'ECO',name:'Economics',categoryId:'CAT-COM',mediums:['English','Gujarati'],description:'Economics and applied analysis.',classes:['11','12'],streamIds:['STR-COM','STR-ART'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:false,bestOfEligible:false,cgpaApplicable:false,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:true,status:'Active' },
  { id:'SUB-HIS',code:'HIS',name:'History',categoryId:'CAT-CORE',mediums:['English','Gujarati'],description:'History and social studies.',classes:['9','10','11','12'],streamIds:['STR-ART'],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:true,bestOfEligible:true,cgpaApplicable:true,boardExamApplicable:true,boardExamType:'Theory',externalMarksEntry:true,status:'Active' },
  { id:'SUB-CS',code:'CS',name:'Computer Science',categoryId:'CAT-SKILL',mediums:['English'],description:'Computing fundamentals and practical programming.',classes:['9','10','11','12'],streamIds:['STR-SCI','STR-COM'],passPercent:33,theoryMinimum:20,practicalMinimum:13,separateTheoryPass:true,separatePracticalPass:true,replacementEligible:false,bestOfEligible:false,cgpaApplicable:true,boardExamApplicable:true,boardExamType:'Both',externalMarksEntry:true,status:'Active' },
  { id:'SUB-PE',code:'PE',name:'Physical Education',categoryId:'CAT-SKILL',mediums:['English','Gujarati'],description:'Physical education, wellness, and activity skills.',classes:['9','10','11','12'],streamIds:['STR-SCI','STR-COM','STR-ART'],passPercent:33,theoryMinimum:20,practicalMinimum:13,separateTheoryPass:true,separatePracticalPass:true,replacementEligible:false,bestOfEligible:false,cgpaApplicable:true,boardExamApplicable:false,boardExamType:'Practical',externalMarksEntry:false,status:'Active' }
];
const seedRules: SubjectGroupRule[] = [
  { id:'RULE-SCI', name:'Science Group', classes:['11','12'], streamIds:['STR-SCI'], minSubjects:5, maxSubjects:6, subjectIds:['SUB-ENG','SUB-PHY','SUB-CHE','SUB-MAT','SUB-BIO','SUB-CS'], mandatorySubjectIds:['SUB-ENG','SUB-PHY','SUB-CHE'], active:true },
  { id:'RULE-COM', name:'Commerce Group', classes:['11','12'], streamIds:['STR-COM'], minSubjects:5, maxSubjects:6, subjectIds:['SUB-ENG','SUB-ACC','SUB-BST','SUB-ECO','SUB-MAT','SUB-CS'], mandatorySubjectIds:['SUB-ENG','SUB-ACC','SUB-BST'], active:true },
  { id:'RULE-ART', name:'Arts & Humanities Group', classes:['11','12'], streamIds:['STR-ART'], minSubjects:5, maxSubjects:6, subjectIds:['SUB-ENG','SUB-HIS','SUB-ECO','SUB-GUJ','SUB-PE','SUB-CS'], mandatorySubjectIds:['SUB-ENG','SUB-HIS'], active:true }
];
const loadState = (): any => { if (typeof window === 'undefined') return {}; try { return JSON.parse(window.localStorage.getItem(STORAGE_KEY) || '{}'); } catch { return {}; } };
const emptySubject = (): Subject => ({ id:`SUB-${Date.now()}`,code:'',name:'',categoryId:'',mediums:['English'],description:'',classes:[],streamIds:[],passPercent:33,theoryMinimum:33,practicalMinimum:0,separateTheoryPass:false,separatePracticalPass:false,replacementEligible:false,bestOfEligible:false,cgpaApplicable:true,boardExamApplicable:false,boardExamType:'Theory',externalMarksEntry:false,status:'Active' });
const emptyCategory = (): SubjectCategory => ({ id:`CAT-${Date.now()}`,name:'',code:'',description:'',displayOrder:1,status:'Active',subjectTypeName:'Academic',classification:emptyClassification(),components:[{id:`MC-${Date.now()}`,name:'Theory',maxMarks:100}] });
const emptyGroup = (): SubjectGroupRule => ({ id:`RULE-${Date.now()}`,name:'',classes:[],streamIds:[],minSubjects:1,maxSubjects:1,subjectIds:[],mandatorySubjectIds:[],active:true });
const componentTotal = (components: MarkComponent[]) => components.reduce((sum, component) => sum + (Number(component.maxMarks) || 0), 0);

export function StreamSubjectGroupMaster() {
  const stored = useMemo(loadState, []);
  const [streams,setStreams] = useState<Stream[]>(Array.isArray(stored.streams)?stored.streams:seedStreams);
  const initialCategories: SubjectCategory[] = Array.isArray(stored.categories) ? stored.categories.map((item: any) => { const clean = { ...item }; delete clean.usedBySubjectIds; return clean; }) : seedCategories;
  const [categories,setCategories] = useState<SubjectCategory[]>(initialCategories);
  const [subjects,setSubjects] = useState<Subject[]>(Array.isArray(stored.subjects)?stored.subjects:seedSubjects);
  const [rules,setRules] = useState<SubjectGroupRule[]>(Array.isArray(stored.rules)?stored.rules:seedRules);
  const [activeTab,setActiveTab] = useState<ActiveTab>('streams');
  const [streamDraft,setStreamDraft] = useState<Stream|null>(null);
  const [categoryDraft,setCategoryDraft] = useState<SubjectCategory|null>(null);
  const [ruleDraft,setRuleDraft] = useState<SubjectGroupRule|null>(null);
  const [subjectDraft,setSubjectDraft] = useState<Subject|null>(null);
  const [search,setSearch] = useState('');
  const [categorySearch,setCategorySearch] = useState('');
  const [subjectSearch,setSubjectSearch] = useState('');
  const [subjectCategoryFilter,setSubjectCategoryFilter] = useState('All Categories');
  const [subjectClassFilter,setSubjectClassFilter] = useState('All Classes');
  const [subjectStatusFilter,setSubjectStatusFilter] = useState('All Status');
  const [toast,setToast] = useState('');
  const [categoryPreset,setCategoryPreset] = useState('Custom');

  useEffect(() => { try { window.localStorage.setItem(STORAGE_KEY,JSON.stringify({streams,categories,subjects,rules})); } catch { /* remains usable locally */ } },[streams,categories,subjects,rules]);
  const notify = (message:string) => { setToast(message); window.setTimeout(()=>setToast(''),3200); };
  const streamsForClass = (classCode:string) => streams.filter((stream)=>stream.classes.includes(classCode)&&stream.active);
  const visibleStreams = streams.filter((stream)=>`${stream.name} ${stream.code} ${stream.classes.join(' ')}`.toLowerCase().includes(search.toLowerCase()));
  const visibleCategories = categories.filter((category)=>`${category.name} ${category.code} ${category.description}`.toLowerCase().includes(categorySearch.toLowerCase()));
  const visibleSubjects = useMemo(()=>subjects.filter((subject)=>{
    const haystack=`${subject.name} ${subject.code} ${categories.find((category)=>category.id===subject.categoryId)?.name||''}`.toLowerCase();
    return (!subjectSearch||haystack.includes(subjectSearch.toLowerCase()))&&(subjectCategoryFilter==='All Categories'||subject.categoryId===subjectCategoryFilter)&&(subjectClassFilter==='All Classes'||subject.classes.includes(subjectClassFilter))&&(subjectStatusFilter==='All Status'||subject.status===subjectStatusFilter);
  }),[subjects,categories,subjectSearch,subjectCategoryFilter,subjectClassFilter,subjectStatusFilter]);

  const saveStream = () => {
    if(!streamDraft?.name.trim()||!streamDraft.code.trim()||!streamDraft.classes.length){notify('Enter stream name, code, and at least one applicable class.');return;}
    const code=streamDraft.code.trim().toUpperCase();
    if(streams.some((item)=>item.id!==streamDraft.id&&item.code.toUpperCase()===code)){notify(`Stream code ${code} already exists.`);return;}
    const saved={...streamDraft,name:streamDraft.name.trim(),code,classes:[...new Set(streamDraft.classes)].sort((a,b)=>CLASSES.indexOf(a)-CLASSES.indexOf(b))};
    setStreams((prev)=>prev.some((item)=>item.id===saved.id)?prev.map((item)=>item.id===saved.id?saved:item):[saved,...prev]);
    setStreamDraft(null);notify(`${saved.name} saved.`);
  };
  const saveCategory = () => {
    if(!categoryDraft?.name.trim()||!categoryDraft.code.trim()){notify('Enter a category name and code.');return;}
    const total=componentTotal(categoryDraft.components);
    if(total!==100){notify(`Marks components must add up to exactly 100. Current total: ${total}.`);return;}
    if(!categoryDraft.components.some((component)=>component.name.trim())){notify('Add at least one named marks component.');return;}
    const code=categoryDraft.code.trim().toUpperCase();
    if(categories.some((item)=>item.id!==categoryDraft.id&&item.code.toUpperCase()===code)){notify(`Category code ${code} already exists.`);return;}
    const savedCategory={...categoryDraft,code,name:categoryDraft.name.trim()};
    setCategories((prev)=>prev.some((item)=>item.id===savedCategory.id)?prev.map((item)=>item.id===savedCategory.id?savedCategory:item):[savedCategory,...prev]);
    setCategoryDraft(null);notify(`${savedCategory.name} category saved with 100 total marks.`);
  };
  const saveRule = () => {
    if(!ruleDraft?.name.trim()){notify('Enter a subject group rule name.');return;}
    if(ruleDraft.minSubjects<1||ruleDraft.maxSubjects<ruleDraft.minSubjects){notify('Maximum subjects must be greater than or equal to the minimum.');return;}
    if(ruleDraft.maxSubjects>ruleDraft.subjectIds.length){notify('Maximum subjects cannot exceed the number of eligible subjects.');return;}
    if(ruleDraft.mandatorySubjectIds.length>ruleDraft.maxSubjects){notify('Mandatory subject count cannot exceed the maximum group size.');return;}
    const saved={...ruleDraft,name:ruleDraft.name.trim(),mandatorySubjectIds:ruleDraft.mandatorySubjectIds.filter((id)=>ruleDraft.subjectIds.includes(id))};
    setRules((prev)=>prev.some((item)=>item.id===saved.id)?prev.map((item)=>item.id===saved.id?saved:item):[saved,...prev]);
    setRuleDraft(null);notify(`${saved.name} saved.`);
  };
  const saveSubject = () => {
    if(!subjectDraft?.name.trim()||!subjectDraft.code.trim()||!subjectDraft.categoryId){notify('Enter subject name, code, and a subject category.');return;}
    if(!subjectDraft.classes.length){notify('Select at least one applicable class.');return;}
    if(subjectDraft.passPercent<0||subjectDraft.passPercent>100||subjectDraft.theoryMinimum<0||subjectDraft.theoryMinimum>100||subjectDraft.practicalMinimum<0||subjectDraft.practicalMinimum>100){notify('Pass percentages and minimum marks must be between 0 and 100.');return;}
    const code=subjectDraft.code.trim().toUpperCase();
    if(subjects.some((item)=>item.id!==subjectDraft.id&&item.code.toUpperCase()===code)){notify(`Subject code ${code} already exists.`);return;}
    const isSenior=subjectDraft.classes.some((item)=>['11','12'].includes(item));
    const selectedStreams=subjectDraft.streamIds.filter((id)=>streams.some((stream)=>stream.id===id&&stream.classes.some((classCode)=>subjectDraft.classes.includes(classCode))));
    const saved={...subjectDraft,code,name:subjectDraft.name.trim(),streamIds:isSenior?selectedStreams:[]};
    setSubjects((prev)=>prev.some((item)=>item.id===saved.id)?prev.map((item)=>item.id===saved.id?saved:item):[saved,...prev]);
    setSubjectDraft(null);notify(`${saved.name} subject saved.`);
  };
  const applyCategoryPreset=(preset:string)=>{
    if(!categoryDraft)return;
    setCategoryPreset(preset);
    const options:Record<string, {type:string;flags:SubjectClassification;components:MarkComponent[]}>= {
      'Academic core':{type:'Academic',flags:{...emptyClassification(),core:true,boardExam:true},components:[{id:`MC-${Date.now()}`,name:'Written',maxMarks:100}]},
      'Language':{type:'Language',flags:{...emptyClassification(),language:true,core:true},components:[{id:`MC-${Date.now()}`,name:'Written',maxMarks:80},{id:`MC-${Date.now()+1}`,name:'Internal Assessment',maxMarks:20}]},
      'Theory + practical 70/30':{type:'Academic',flags:{...emptyClassification(),core:true,practical:true,boardExam:true},components:[{id:`MC-${Date.now()}`,name:'Theory',maxMarks:70},{id:`MC-${Date.now()+1}`,name:'Practical',maxMarks:30}]},
      'Theory + practical 60/40':{type:'Skill',flags:{...emptyClassification(),skill:true,vocational:true,practical:true},components:[{id:`MC-${Date.now()}`,name:'Theory',maxMarks:60},{id:`MC-${Date.now()+1}`,name:'Practical',maxMarks:40}]},
      'Theory + internal 80/20':{type:'Academic',flags:{...emptyClassification(),core:true},components:[{id:`MC-${Date.now()}`,name:'Theory',maxMarks:80},{id:`MC-${Date.now()+1}`,name:'Internal Assessment',maxMarks:20}]}
    };
    const picked=options[preset];if(picked)setCategoryDraft((prev)=>prev?{...prev,subjectTypeName:picked.type,classification:picked.flags,components:picked.components}:prev);
  };
  const updateCategoryComponent=(id:string,patch:Partial<MarkComponent>)=>setCategoryDraft((prev)=>prev?{...prev,components:prev.components.map((component)=>component.id===id?{...component,...patch}:component)}:prev);
  const toggleStreamClass=(classCode:string)=>setStreamDraft((prev)=>prev?{...prev,classes:prev.classes.includes(classCode)?prev.classes.filter((item)=>item!==classCode):[...prev.classes,classCode]}:prev);
  const toggleSubjectClass=(classCode:string)=>setSubjectDraft((prev)=>{if(!prev)return prev;const classes=prev.classes.includes(classCode)?prev.classes.filter((item)=>item!==classCode):[...prev.classes,classCode];return{...prev,classes,streamIds:classes.some((item)=>['11','12'].includes(item))?prev.streamIds:[]};});
  const toggleGroupSubject=(subjectId:string)=>setRuleDraft((prev)=>prev?{...prev,subjectIds:prev.subjectIds.includes(subjectId)?prev.subjectIds.filter((id)=>id!==subjectId):[...prev.subjectIds,subjectId],mandatorySubjectIds:prev.subjectIds.includes(subjectId)?prev.mandatorySubjectIds.filter((id)=>id!==subjectId):prev.mandatorySubjectIds}:prev);
  const toggleRuleMandatory=(subjectId:string)=>setRuleDraft((prev)=>prev?{...prev,mandatorySubjectIds:prev.mandatorySubjectIds.includes(subjectId)?prev.mandatorySubjectIds.filter((id)=>id!==subjectId):[...prev.mandatorySubjectIds,subjectId]}:prev);
  const toggleSubjectMedium=(medium:string)=>setSubjectDraft((prev)=>prev?{...prev,mediums:prev.mediums.includes(medium)?prev.mediums.filter((item)=>item!==medium):[...prev.mediums,medium]}:prev);
  const toggleSubjectStream=(streamId:string)=>setSubjectDraft((prev)=>prev?{...prev,streamIds:prev.streamIds.includes(streamId)?prev.streamIds.filter((id)=>id!==streamId):[...prev.streamIds,streamId]}:prev);
  const selectedCategory=subjectDraft?categories.find((category)=>category.id===subjectDraft.categoryId):undefined;
  const availableSubjectStreams=subjectDraft?.classes.flatMap((classCode)=>streamsForClass(classCode))||[];
  const uniqueApplicableStreams=Array.from(new Map(availableSubjectStreams.map((stream)=>[stream.id,stream])).values());

  return <div className="space-y-6 px-4 py-6 sm:px-6 lg:px-8">
    <header className="flex flex-wrap items-start justify-between gap-3 border-b border-gray-200 pb-4"><div><div className="flex items-center gap-2 text-xs text-gray-500"><span>Home</span><ChevronRight className="h-3 w-3"/><span>Masters</span><ChevronRight className="h-3 w-3"/><span>Academic Setup</span></div><h1 className="mt-1 text-2xl font-bold text-gray-900">Stream &amp; Subject Group Master</h1><p className="mt-1 text-sm text-gray-500">Configure streams, subject categories, group rules, and subjects together.</p></div><div className="flex flex-wrap gap-2"><Badge variant="info">{streams.length} streams</Badge><Badge variant="info">{categories.length} categories</Badge><Badge variant="info">{subjects.length} subjects</Badge></div></header>
    <nav className="flex flex-wrap gap-1 rounded-xl border border-gray-200 bg-white p-1">{([['streams','Streams'],['categories','Subject Category · MASTER 0'],['rules','Subject Group Rules'],['subjects','Subject Master · MASTER 1']] as Array<[ActiveTab,string]>).map(([tab,label])=><button key={tab} onClick={()=>setActiveTab(tab)} className={`rounded-lg px-4 py-2.5 text-xs font-semibold transition-colors ${activeTab===tab?'bg-indigo-600 text-white shadow-sm':'text-gray-600 hover:bg-gray-50'}`}>{label}</button>)}</nav>
    {activeTab==='streams'&&<section className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-bold">Streams &amp; Applicable Classes</h2><p className="text-xs text-gray-500">A stream identifies its name, short code, and classes only. Subject assignments are managed below in Subject Master.</p></div><div className="flex gap-2"><label className="relative"><Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400"/><input value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Search streams" className="rounded-md border py-2 pl-8 pr-3 text-xs"/></label><Button onClick={()=>setStreamDraft({id:`STR-${Date.now()}`,name:'',code:'',classes:[],active:true})}><Plus className="mr-1.5 h-4 w-4"/>Create Stream</Button></div></div><div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">{visibleStreams.map((stream)=><article key={stream.id} className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><div><p className="font-mono text-xs text-indigo-700">{stream.code}</p><h3 className="mt-1 text-lg font-bold">{stream.name}</h3><p className="mt-1 text-xs text-gray-500">{stream.classes.length} applicable classes</p></div><Badge variant={stream.active?'success':'default'}>{stream.active?'Active':'Inactive'}</Badge></div><div className="mt-4 flex flex-wrap gap-2">{stream.classes.map((classCode)=><span key={classCode} className="rounded-full border border-gray-200 bg-gray-50 px-2.5 py-1 text-[11px]">Class {classCode}</span>)}</div><div className="mt-4 flex justify-end gap-2 border-t pt-3"><Button variant="outline" size="sm" onClick={()=>setStreamDraft({...stream})}><Edit3 className="mr-1 h-3.5 w-3.5"/>Edit</Button><Button variant="ghost" size="sm" onClick={()=>{if(window.confirm(`Delete ${stream.name}?`)){setStreams((prev)=>prev.filter((item)=>item.id!==stream.id));setSubjects((prev)=>prev.map((subject)=>({...subject,streamIds:subject.streamIds.filter((id)=>id!==stream.id)})));setRules((prev)=>prev.map((rule)=>({...rule,streamIds:rule.streamIds.filter((id)=>id!==stream.id)})));}}}><Trash2 className="mr-1 h-3.5 w-3.5"/>Delete</Button></div></article>)}{visibleStreams.length===0&&<div className="col-span-full rounded-xl border border-dashed p-10 text-center text-sm text-gray-500">No streams found.</div>}</div><div className="rounded-xl border border-blue-100 bg-blue-50 p-4 text-xs text-blue-900"><strong>Design note:</strong> Stream definitions intentionally do not contain subjects. Select applicable streams for each subject in the Subject Master panel.</div></section>}
    {activeTab==='categories'&&<section className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-bold">Subject Category <span className="text-sm font-semibold text-indigo-700">MASTER 0</span></h2><p className="text-xs text-gray-500">Define classification flags and marks components once; subjects inherit the selected category setup.</p></div><div className="flex gap-2"><label className="relative"><Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400"/><input value={categorySearch} onChange={(e)=>setCategorySearch(e.target.value)} placeholder="Search categories" className="rounded-md border py-2 pl-8 pr-3 text-xs"/></label><Button onClick={()=>{setCategoryDraft(emptyCategory());setCategoryPreset('Custom');}}><Plus className="mr-1.5 h-4 w-4"/>Create Category</Button></div></div><div className="overflow-hidden rounded-xl border border-gray-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[820px] text-left text-xs"><thead><tr className="bg-gray-50"><th className="p-3 text-[10px] uppercase text-gray-500">Category</th><th className="p-3 text-[10px] uppercase text-gray-500">Subject Type</th><th className="p-3 text-[10px] uppercase text-gray-500">Classification Flags</th><th className="p-3 text-[10px] uppercase text-gray-500">Marks Components</th><th className="p-3 text-[10px] uppercase text-gray-500">Status</th><th className="p-3 text-right text-[10px] uppercase text-gray-500">Action</th></tr></thead><tbody className="divide-y">{visibleCategories.map((category)=><tr key={category.id} className="hover:bg-gray-50"><td className="p-3"><strong>{category.name}</strong><span className="mt-1 block font-mono text-[10px] text-indigo-700">{category.code} · order {category.displayOrder}</span><span className="mt-1 block text-[10px] text-gray-500">{category.description}</span></td><td className="p-3">{category.subjectTypeName}</td><td className="p-3"><div className="flex max-w-[210px] flex-wrap gap-1">{CLASSIFICATION_LABELS.filter(([key])=>category.classification[key]).map(([key,label])=><span key={key} className="rounded bg-violet-50 px-1.5 py-1 text-[10px] text-violet-700">{label}</span>)}</div></td><td className="p-3">{category.components.map((component)=><span key={component.id} className="mr-1 inline-block rounded bg-gray-100 px-2 py-1 text-[10px]">{component.name}: {component.maxMarks}</span>)}<span className={`mt-1 block font-semibold ${componentTotal(category.components)===100?'text-emerald-700':'text-red-700'}`}>Total {componentTotal(category.components)} / 100</span></td><td className="p-3"><Badge variant={category.status==='Active'?'success':'default'}>{category.status}</Badge></td><td className="p-3 text-right"><Button variant="outline" size="sm" onClick={()=>{setCategoryDraft({...category,classification:{...category.classification},components:category.components.map((item)=>({...item})),});setCategoryPreset('Custom');}}><Edit3 className="mr-1 h-3.5 w-3.5"/>Edit</Button></td></tr>)}{visibleCategories.length===0&&<tr><td colSpan={6} className="p-10 text-center text-gray-500">No categories found.</td></tr>}</tbody></table></div></div></section>}
    {activeTab==='rules'&&<section className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-bold">Subject Group Rules</h2><p className="text-xs text-gray-500">Set group size limits, eligible subjects, and mandatory subject toggles.</p></div><Button onClick={()=>setRuleDraft(emptyGroup())}><Plus className="mr-1.5 h-4 w-4"/>Create Group Rule</Button></div><div className="grid grid-cols-1 gap-4 xl:grid-cols-2">{rules.map((rule)=><article key={rule.id} className="rounded-xl border border-gray-200 bg-white p-5"><div className="flex items-start justify-between"><div><h3 className="font-bold">{rule.name}</h3><p className="mt-1 text-xs text-gray-500">Classes {rule.classes.map((item)=>`Class ${item}`).join(', ')||'—'} · {rule.streamIds.map((id)=>streams.find((stream)=>stream.id===id)?.name).filter(Boolean).join(', ')||'All streams'}</p></div><Badge variant={rule.active?'success':'default'}>{rule.active?'Active':'Inactive'}</Badge></div><div className="mt-4 grid grid-cols-3 gap-2 rounded-lg bg-gray-50 p-3 text-center"><div><span className="block text-[10px] uppercase text-gray-500">Minimum</span><strong>{rule.minSubjects}</strong></div><div><span className="block text-[10px] uppercase text-gray-500">Maximum</span><strong>{rule.maxSubjects}</strong></div><div><span className="block text-[10px] uppercase text-gray-500">Mandatory</span><strong>{rule.mandatorySubjectIds.length}</strong></div></div><div className="mt-3"><p className="mb-2 text-[10px] font-bold uppercase text-gray-500">Eligible &amp; mandatory subjects</p><div className="flex flex-wrap gap-1.5">{rule.subjectIds.map((id)=>{const subject=subjects.find((item)=>item.id===id);if(!subject)return null;const mandatory=rule.mandatorySubjectIds.includes(id);return <span key={id} className={`rounded-full px-2.5 py-1 text-[10px] ${mandatory?'bg-amber-100 font-semibold text-amber-900':'bg-gray-100 text-gray-700'}`}>{subject.name}{mandatory?' · Mandatory':''}</span>;})}</div></div><div className="mt-4 flex justify-end gap-2 border-t pt-3"><Button variant="outline" size="sm" onClick={()=>setRuleDraft({...rule,classes:[...rule.classes],streamIds:[...rule.streamIds],subjectIds:[...rule.subjectIds],mandatorySubjectIds:[...rule.mandatorySubjectIds]})}><Edit3 className="mr-1 h-3.5 w-3.5"/>Edit Rules</Button><Button variant="ghost" size="sm" onClick={()=>{if(window.confirm(`Delete ${rule.name}?`))setRules((prev)=>prev.filter((item)=>item.id!==rule.id));}}><Trash2 className="mr-1 h-3.5 w-3.5"/>Delete</Button></div></article>)}{rules.length===0&&<div className="col-span-full rounded-xl border border-dashed p-10 text-center text-sm text-gray-500">No subject group rules yet.</div>}</div></section>}
    {activeTab==='subjects'&&<section className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-bold">Subject Master <span className="text-sm font-semibold text-indigo-700">MASTER 1</span></h2><p className="text-xs text-gray-500">Configure category inheritance, medium, class/stream applicability, pass rules, and board examination details.</p></div><div className="flex flex-wrap gap-2"><label className="relative"><Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400"/><input value={subjectSearch} onChange={(e)=>setSubjectSearch(e.target.value)} placeholder="Search subjects" className="rounded-md border py-2 pl-8 pr-3 text-xs"/></label><Button onClick={()=>setSubjectDraft(emptySubject())}><Plus className="mr-1.5 h-4 w-4"/>Create Subject</Button></div></div><div className="grid grid-cols-1 gap-3 rounded-xl border border-gray-200 bg-white p-4 md:grid-cols-3"><label className="text-[10px] font-semibold text-gray-500">CATEGORY<select value={subjectCategoryFilter} onChange={(e)=>setSubjectCategoryFilter(e.target.value)} className="mt-1 w-full rounded-md border p-2 text-xs font-normal"><option>All Categories</option>{categories.map((category)=><option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label className="text-[10px] font-semibold text-gray-500">CLASS<select value={subjectClassFilter} onChange={(e)=>setSubjectClassFilter(e.target.value)} className="mt-1 w-full rounded-md border p-2 text-xs font-normal"><option>All Classes</option>{CLASSES.map((classCode)=><option key={classCode} value={classCode}>{classCode==='KG'||classCode==='Nursery'?classCode:`Class ${classCode}`}</option>)}</select></label><label className="text-[10px] font-semibold text-gray-500">STATUS<select value={subjectStatusFilter} onChange={(e)=>setSubjectStatusFilter(e.target.value)} className="mt-1 w-full rounded-md border p-2 text-xs font-normal"><option>All Status</option><option>Active</option><option>Inactive</option></select></label></div><div className="overflow-hidden rounded-xl border border-gray-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[1180px] text-left text-xs"><thead><tr className="bg-gray-50"><th className="p-3 text-[10px] uppercase text-gray-500">Subject</th><th className="p-3 text-[10px] uppercase text-gray-500">Category / Marks setup</th><th className="p-3 text-[10px] uppercase text-gray-500">Classes &amp; streams</th><th className="p-3 text-[10px] uppercase text-gray-500">Medium</th><th className="p-3 text-[10px] uppercase text-gray-500">Pass / Board setup</th><th className="p-3 text-[10px] uppercase text-gray-500">Status</th><th className="p-3 text-right text-[10px] uppercase text-gray-500">Action</th></tr></thead><tbody className="divide-y">{visibleSubjects.map((subject)=><tr key={subject.id} className="hover:bg-gray-50"><td className="p-3"><strong>{subject.name}</strong><span className="mt-1 block font-mono text-[10px] text-indigo-700">{subject.code}</span><span className="mt-1 block max-w-[200px] text-[10px] text-gray-500">{subject.description}</span></td><td className="p-3"><strong>{categories.find((category)=>category.id===subject.categoryId)?.name||'Unassigned'}</strong><span className="mt-1 block text-[10px] text-gray-500">{categories.find((category)=>category.id===subject.categoryId)?.components.map((component)=>`${component.name} ${component.maxMarks}`).join(' · ')||'Set a category'}</span><span className="mt-1 block text-[10px] font-semibold text-indigo-700">Category marks total: {componentTotal(categories.find((category)=>category.id===subject.categoryId)?.components||[])} / 100</span></td><td className="p-3"><div>{subject.classes.map((item)=>`Class ${item}`).join(', ')||'—'}</div><span className="mt-1 block text-[10px] text-gray-500">{subject.streamIds.map((id)=>streams.find((stream)=>stream.id===id)?.name).filter(Boolean).join(', ')||'No stream set'}</span></td><td className="p-3">{subject.mediums.join(', ')||'—'}</td><td className="p-3">Pass {subject.passPercent}%<span className="mt-1 block text-[10px] text-gray-500">{subject.separateTheoryPass?'Theory min '+subject.theoryMinimum+' · ':''}{subject.separatePracticalPass?'Practical min '+subject.practicalMinimum+' · ':''}{subject.boardExamApplicable?`${subject.boardExamType} board exam`:'No board exam'}</span></td><td className="p-3"><Badge variant={subject.status==='Active'?'success':'default'}>{subject.status}</Badge></td><td className="p-3 text-right"><div className="flex justify-end gap-1"><Button variant="outline" size="sm" onClick={()=>setSubjectDraft({...subject,classes:[...subject.classes],streamIds:[...subject.streamIds],mediums:[...subject.mediums]})}><Edit3 className="mr-1 h-3.5 w-3.5"/>Edit</Button><Button variant="ghost" size="sm" onClick={()=>{if(window.confirm(`Delete ${subject.name}?`)){setSubjects((prev)=>prev.filter((item)=>item.id!==subject.id));setRules((prev)=>prev.map((rule)=>({...rule,subjectIds:rule.subjectIds.filter((id)=>id!==subject.id),mandatorySubjectIds:rule.mandatorySubjectIds.filter((id)=>id!==subject.id)})));}}}><Trash2 className="mr-1 h-3.5 w-3.5"/>Delete</Button></div></td></tr>)}{visibleSubjects.length===0&&<tr><td colSpan={7} className="p-10 text-center text-gray-500">No subjects match your search and filters.</td></tr>}</tbody></table></div></div></section>}

    <Modal isOpen={!!streamDraft} onClose={()=>setStreamDraft(null)} title={streamDraft?.id.startsWith('STR-')&&streams.some((stream)=>stream.id===streamDraft.id)?'Edit Stream':'Create Stream'} size="lg">{streamDraft&&<div className="space-y-4 text-xs"><p className="text-gray-500">Streams contain only their name, code, and applicable classes. Choose subject-stream links within individual subject records.</p><div className="grid grid-cols-1 gap-3 md:grid-cols-2"><label className="text-gray-600">Stream name<input value={streamDraft.name} onChange={(e)=>setStreamDraft((prev)=>prev?{...prev,name:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2" placeholder="e.g. Science"/></label><label className="text-gray-600">Stream code<input value={streamDraft.code} onChange={(e)=>setStreamDraft((prev)=>prev?{...prev,code:e.target.value.toUpperCase()}:prev)} className="mt-1 w-full rounded-md border p-2 font-mono" placeholder="e.g. SCI"/></label><label className="text-gray-600 md:col-span-2">Status<select value={streamDraft.active?'Active':'Inactive'} onChange={(e)=>setStreamDraft((prev)=>prev?{...prev,active:e.target.value==='Active'}:prev)} className="mt-1 w-full rounded-md border p-2"><option>Active</option><option>Inactive</option></select></label></div><div><p className="mb-2 font-semibold text-gray-700">Applicable classes <span className="text-red-600">*</span></p><div className="grid grid-cols-3 gap-2 sm:grid-cols-5">{CLASSES.map((classCode)=><label key={classCode} className="flex items-center gap-2 rounded-lg border p-2 text-gray-700"><input type="checkbox" checked={streamDraft.classes.includes(classCode)} onChange={()=>toggleStreamClass(classCode)}/>{classCode==='KG'||classCode==='Nursery'?classCode:`Class ${classCode}`}</label>)}</div></div><div className="flex justify-end gap-2 border-t pt-3"><Button variant="outline" onClick={()=>setStreamDraft(null)}>Cancel</Button><Button onClick={saveStream}><Check className="mr-1.5 h-4 w-4"/>Save Stream</Button></div></div>}</Modal>

    <Modal isOpen={!!categoryDraft} onClose={()=>setCategoryDraft(null)} title={categoryDraft&&categories.some((item)=>item.id===categoryDraft.id)?'Edit Subject Category · MASTER 0':'Create Subject Category · MASTER 0'} size="xl">{categoryDraft&&<div className="max-h-[78vh] space-y-4 overflow-y-auto text-xs"><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><label className="text-gray-600">Category name<input value={categoryDraft.name} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,name:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="text-gray-600">Category code<input value={categoryDraft.code} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,code:e.target.value.toUpperCase()}:prev)} className="mt-1 w-full rounded-md border p-2 font-mono"/></label><label className="text-gray-600">Display order<input type="number" min={1} value={categoryDraft.displayOrder} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,displayOrder:Number(e.target.value)}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="text-gray-600">Subject type name<input value={categoryDraft.subjectTypeName} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,subjectTypeName:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2" placeholder="Academic / Language / Skill"/></label><label className="text-gray-600">Status<select value={categoryDraft.status} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,status:e.target.value as SubjectCategory['status']}:prev)} className="mt-1 w-full rounded-md border p-2"><option>Active</option><option>Inactive</option></select></label><label className="text-gray-600 md:col-span-3">Description<textarea value={categoryDraft.description} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,description:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2" rows={2}/></label></div><div className="rounded-xl border p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-bold">Independent classification flags</h3><p className="text-[10px] text-gray-500">Flags can be combined; selecting one never clears another.</p></div><select value={categoryPreset} onChange={(e)=>applyCategoryPreset(e.target.value)} className="rounded-md border p-2 text-xs"><option>Custom</option><option>Academic core</option><option>Language</option><option>Theory + practical 70/30</option><option>Theory + practical 60/40</option><option>Theory + internal 80/20</option></select></div><div className="grid grid-cols-2 gap-2 md:grid-cols-4">{CLASSIFICATION_LABELS.map(([key,label])=><label key={key} className="flex items-center gap-2 rounded-lg border p-2"><input type="checkbox" checked={categoryDraft.classification[key]} onChange={(e)=>setCategoryDraft((prev)=>prev?{...prev,classification:{...prev.classification,[key]:e.target.checked}}:prev)}/>{label}</label>)}</div></div><div className="rounded-xl border p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="font-bold">Marks components &amp; presets</h3><p className="text-[10px] text-gray-500">Total must be exactly 100 marks before saving.</p></div><Button variant="outline" size="sm" onClick={()=>setCategoryDraft((prev)=>prev?{...prev,components:[...prev.components,{id:`MC-${Date.now()}`,name:'',maxMarks:0}]}:prev)}><Plus className="mr-1 h-3.5 w-3.5"/>Add Component</Button></div><div className="mt-3 space-y-2">{categoryDraft.components.map((component,index)=><div key={component.id} className="grid grid-cols-[1fr_120px_auto] gap-2"><label className="text-[10px] text-gray-500">Component {index+1} name<input value={component.name} onChange={(e)=>updateCategoryComponent(component.id,{name:e.target.value})} className="mt-1 w-full rounded-md border p-2 text-xs" placeholder="Theory / Practical / Internal"/></label><label className="text-[10px] text-gray-500">Maximum<input type="number" min={0} value={component.maxMarks} onChange={(e)=>updateCategoryComponent(component.id,{maxMarks:Number(e.target.value)})} className="mt-1 w-full rounded-md border p-2 text-xs"/></label><button className="mt-5 rounded-md p-2 text-gray-500 hover:bg-red-50 hover:text-red-700" disabled={categoryDraft.components.length===1} onClick={()=>setCategoryDraft((prev)=>prev?{...prev,components:prev.components.filter((item)=>item.id!==component.id)}:prev)} title="Remove component"><Trash2 className="h-4 w-4"/></button></div>)}</div><div className={`mt-3 rounded-lg p-3 font-bold ${componentTotal(categoryDraft.components)===100?'bg-emerald-50 text-emerald-800':'bg-amber-50 text-amber-800'}`}>Marks total: {componentTotal(categoryDraft.components)} / 100 {componentTotal(categoryDraft.components)===100?'· Valid':'· Adjust components to total exactly 100'}</div></div><div className="flex justify-end gap-2 border-t pt-3"><Button variant="outline" onClick={()=>setCategoryDraft(null)}>Cancel</Button><Button onClick={saveCategory}><Check className="mr-1.5 h-4 w-4"/>Save Category</Button></div></div>}</Modal>

    <Modal isOpen={!!ruleDraft} onClose={()=>setRuleDraft(null)} title="Subject Group Rule" size="xl">{ruleDraft&&<div className="max-h-[78vh] space-y-4 overflow-y-auto text-xs"><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><label className="text-gray-600">Group / rule name<input value={ruleDraft.name} onChange={(e)=>setRuleDraft((prev)=>prev?{...prev,name:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="text-gray-600">Minimum subjects<input type="number" min={1} value={ruleDraft.minSubjects} onChange={(e)=>setRuleDraft((prev)=>prev?{...prev,minSubjects:Number(e.target.value)}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="text-gray-600">Maximum subjects<input type="number" min={1} value={ruleDraft.maxSubjects} onChange={(e)=>setRuleDraft((prev)=>prev?{...prev,maxSubjects:Number(e.target.value)}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="text-gray-600 md:col-span-2">Applicable classes<div className="mt-1 flex flex-wrap gap-2">{CLASSES.map((classCode)=><label key={classCode} className="flex items-center gap-1 rounded border px-2 py-1"><input type="checkbox" checked={ruleDraft.classes.includes(classCode)} onChange={(e)=>setRuleDraft((prev)=>prev?{...prev,classes:e.target.checked?[...prev.classes,classCode]:prev.classes.filter((item)=>item!==classCode)}:prev)}/>{classCode}</label>)}</div></label><label className="flex items-center gap-2 text-gray-600"><input type="checkbox" checked={ruleDraft.active} onChange={(e)=>setRuleDraft((prev)=>prev?{...prev,active:e.target.checked}:prev)}/>Rule active</label><div className="md:col-span-3"><p className="mb-2 font-semibold text-gray-700">Applicable streams</p><div className="flex flex-wrap gap-2">{streams.map((stream)=><label key={stream.id} className="flex items-center gap-2 rounded-lg border p-2"><input type="checkbox" checked={ruleDraft.streamIds.includes(stream.id)} onChange={(e)=>setRuleDraft((prev)=>prev?{...prev,streamIds:e.target.checked?[...prev.streamIds,stream.id]:prev.streamIds.filter((id)=>id!==stream.id)}:prev)}/>{stream.name}</label>)}</div></div></div><div><h3 className="mb-2 font-bold">Eligible subjects and mandatory toggles</h3><div className="grid gap-2">{subjects.map((subject)=><div key={subject.id} className="grid grid-cols-[1fr_auto] items-center gap-3 rounded-lg border p-2"><label className="flex items-center gap-2"><input type="checkbox" checked={ruleDraft.subjectIds.includes(subject.id)} onChange={()=>toggleGroupSubject(subject.id)}/><span><strong>{subject.name}</strong><small className="ml-2 text-gray-500">{subject.code} · {categories.find((category)=>category.id===subject.categoryId)?.name||'Unassigned'}</small></span></label><label className={`flex items-center gap-2 rounded-full px-2 py-1 text-[10px] ${ruleDraft.mandatorySubjectIds.includes(subject.id)?'bg-amber-100 text-amber-900':'bg-gray-50 text-gray-500'}`}><input type="checkbox" disabled={!ruleDraft.subjectIds.includes(subject.id)} checked={ruleDraft.mandatorySubjectIds.includes(subject.id)} onChange={()=>toggleRuleMandatory(subject.id)}/>Mandatory</label></div>)}</div></div><div className="flex justify-end gap-2 border-t pt-3"><Button variant="outline" onClick={()=>setRuleDraft(null)}>Cancel</Button><Button onClick={saveRule}><Check className="mr-1.5 h-4 w-4"/>Save Group Rule</Button></div></div>}</Modal>

    <Modal isOpen={!!subjectDraft} onClose={()=>setSubjectDraft(null)} title={subjectDraft&&subjects.some((item)=>item.id===subjectDraft.id)?'Edit Subject · MASTER 1':'Create Subject · MASTER 1'} size="xl">{subjectDraft&&<div className="max-h-[80vh] space-y-4 overflow-y-auto text-xs"><div className="rounded-lg bg-blue-50 p-3 text-blue-900"><strong>Subject Master:</strong> Marks components are inherited from the selected category and must be maintained in MASTER 0.</div><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><BookOpen className="h-4 w-4 text-indigo-600"/>A. Subject &amp; classification</h3><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><label className="text-gray-600">Subject name<input value={subjectDraft.name} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,name:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="text-gray-600">Subject code<input value={subjectDraft.code} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,code:e.target.value.toUpperCase()}:prev)} className="mt-1 w-full rounded-md border p-2 font-mono"/></label><label className="text-gray-600">Subject category<select value={subjectDraft.categoryId} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,categoryId:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2"><option value="">Select category</option>{categories.filter((category)=>category.status==='Active').map((category)=><option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label className="text-gray-600 md:col-span-3">Description<textarea value={subjectDraft.description} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,description:e.target.value}:prev)} className="mt-1 w-full rounded-md border p-2" rows={2}/></label></div>{selectedCategory&&<div className="mt-3 rounded-lg border border-indigo-100 bg-indigo-50 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><strong>{selectedCategory.name} · {selectedCategory.subjectTypeName}</strong><span className="text-[10px] font-bold text-indigo-800">Inherited marks total: {componentTotal(selectedCategory.components)} / 100</span></div><div className="mt-2 flex flex-wrap gap-2">{selectedCategory.components.map((component)=><span key={component.id} className="rounded bg-white px-2 py-1 text-[10px]">{component.name}: {component.maxMarks}</span>)}</div><div className="mt-2 flex flex-wrap gap-1">{CLASSIFICATION_LABELS.filter(([key])=>selectedCategory.classification[key]).map(([key,label])=><Badge key={key} variant="info">{label}</Badge>)}</div></div>}<div className="mt-3"><p className="mb-2 font-semibold text-gray-700">Medium(s)</p><div className="flex flex-wrap gap-2">{MEDIUMS.map((medium)=><label key={medium} className="flex items-center gap-2 rounded-lg border px-3 py-2"><input type="checkbox" checked={subjectDraft.mediums.includes(medium)} onChange={()=>toggleSubjectMedium(medium)}/>{medium}</label>)}</div></div></section><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><Users className="h-4 w-4 text-indigo-600"/>B. Applicable classes &amp; streams</h3><div className="grid grid-cols-3 gap-2 sm:grid-cols-5">{CLASSES.map((classCode)=><label key={classCode} className="flex items-center gap-2 rounded-lg border p-2"><input type="checkbox" checked={subjectDraft.classes.includes(classCode)} onChange={()=>toggleSubjectClass(classCode)}/>{classCode==='KG'||classCode==='Nursery'?classCode:`Class ${classCode}`}</label>)}</div>{subjectDraft.classes.some((item)=>['11','12'].includes(item))&&<div className="mt-4 border-t pt-3"><p className="mb-2 font-semibold text-gray-700">Applicable streams for selected senior classes</p><div className="flex flex-wrap gap-2">{uniqueApplicableStreams.map((stream)=><label key={stream.id} className="flex items-center gap-2 rounded-lg border px-3 py-2"><input type="checkbox" checked={subjectDraft.streamIds.includes(stream.id)} onChange={()=>toggleSubjectStream(stream.id)}/>{stream.name} <small className="font-mono text-gray-400">{stream.code}</small></label>)}{uniqueApplicableStreams.length===0&&<span className="text-gray-500">Create a stream for the selected class first.</span>}</div></div>}</section><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><ShieldCheck className="h-4 w-4 text-indigo-600"/>C. Pass / fail and assessment settings</h3><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><label className="text-gray-600">Minimum pass percentage<input type="number" min={0} max={100} value={subjectDraft.passPercent} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,passPercent:Number(e.target.value)}:prev)} className="mt-1 w-full rounded-md border p-2"/></label><label className="flex items-center gap-2 rounded-lg border p-3"><input type="checkbox" checked={subjectDraft.separateTheoryPass} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,separateTheoryPass:e.target.checked}:prev)}/>Separate theory pass rule</label><label className="text-gray-600">Theory minimum<input type="number" min={0} value={subjectDraft.theoryMinimum} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,theoryMinimum:Number(e.target.value)}:prev)} className="mt-1 w-full rounded-md border p-2" disabled={!subjectDraft.separateTheoryPass}/></label><label className="flex items-center gap-2 rounded-lg border p-3"><input type="checkbox" checked={subjectDraft.separatePracticalPass} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,separatePracticalPass:e.target.checked}:prev)}/>Separate practical pass rule</label><label className="text-gray-600">Practical minimum<input type="number" min={0} value={subjectDraft.practicalMinimum} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,practicalMinimum:Number(e.target.value)}:prev)} className="mt-1 w-full rounded-md border p-2" disabled={!subjectDraft.separatePracticalPass}/></label><label className="text-gray-600">Status<select value={subjectDraft.status} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,status:e.target.value as Subject['status']}:prev)} className="mt-1 w-full rounded-md border p-2"><option>Active</option><option>Inactive</option></select></label></div><div className="mt-3 grid grid-cols-1 gap-2 md:grid-cols-3">{([['replacementEligible','Eligible for replacement subject'],['bestOfEligible','Include in best-of calculation'],['cgpaApplicable','Include in CGPA calculation']] as Array<[keyof Subject,string]>).map(([key,label])=><label key={key} className="flex items-center gap-2 rounded-lg border p-3"><input type="checkbox" checked={Boolean(subjectDraft[key])} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,[key]:e.target.checked}:prev)}/>{label}</label>)}</div></section><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><ClipboardList className="h-4 w-4 text-indigo-600"/>D. Board examination configuration</h3><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><label className="flex items-center gap-2 rounded-lg border p-3"><input type="checkbox" checked={subjectDraft.boardExamApplicable} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,boardExamApplicable:e.target.checked}:prev)}/>Applicable to board examination</label><label className="text-gray-600">Board exam type<select value={subjectDraft.boardExamType} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,boardExamType:e.target.value as Subject['boardExamType']}:prev)} disabled={!subjectDraft.boardExamApplicable} className="mt-1 w-full rounded-md border p-2"><option>Theory</option><option>Practical</option><option>Both</option><option>Oral</option></select></label><label className="flex items-center gap-2 rounded-lg border p-3"><input type="checkbox" checked={subjectDraft.externalMarksEntry} disabled={!subjectDraft.boardExamApplicable} onChange={(e)=>setSubjectDraft((prev)=>prev?{...prev,externalMarksEntry:e.target.checked}:prev)}/>Require external board marks entry</label></div></section><div className="flex justify-end gap-2 border-t pt-3"><Button variant="outline" onClick={()=>setSubjectDraft(null)}>Cancel</Button><Button onClick={saveSubject}><Check className="mr-1.5 h-4 w-4"/>Save Subject</Button></div></div>}</Modal>
    {toast&&<div role="status" className="fixed bottom-5 right-5 z-50 flex items-center gap-2 rounded-xl border border-gray-700 bg-gray-900 px-5 py-3 text-sm text-white shadow-2xl"><Check className="h-4 w-4 text-emerald-400"/>{toast}<button onClick={()=>setToast('')}><X className="h-4 w-4"/></button></div>}
  </div>;
}

export default StreamSubjectGroupMaster;
